// Original native calls once; inputs and immediate actual body state only.
namespace {
void property_event(const char* name,const char* phase,WatchedBody ref,const char* input){
 if(!mutation_enabled())return;if(const char* path=std::getenv("GPU_PR10_API_TRACE"))if(FILE* f=std::fopen(path,"a")){std::fprintf(f,"{\"api\":\"%s\",\"phase\":\"%s\",\"input\":%s,\"body\":",name,phase,input);auto it=std::find_if(mutation_bodies.begin(),mutation_bodies.end(),[&](auto& b){return same_body(b.ref,ref);});if(it!=mutation_bodies.end()&&body_valid(ref))mutation_body_json(f,*it);else body_json(f,ref);std::fputs("}\n",f);std::fclose(f);}
}
}
#define PROPERTY_SCALAR(NAME,CPU) extern "C" void __real_##NAME(b3BodyId,float) __attribute__((weak));extern "C" void __wrap_##NAME(b3BodyId id,float value){assert(__real_##NAME);char input[64];std::snprintf(input,sizeof(input),"[%.9g]",value);property_event(#NAME,"before",{id,CPU},input);__real_##NAME(id,value);property_event(#NAME,"after",{id,CPU},input);}
#define PROPERTY_LOCKS(NAME,CPU) extern "C" void __real_##NAME(b3BodyId,b3MotionLocks) __attribute__((weak));extern "C" void __wrap_##NAME(b3BodyId id,b3MotionLocks locks){assert(__real_##NAME);char input[64];std::snprintf(input,sizeof(input),"[%d]",lock_bits(locks));property_event(#NAME,"before",{id,CPU},input);__real_##NAME(id,locks);property_event(#NAME,"after",{id,CPU},input);}
#define PROPERTY_IMPULSE(NAME,CPU) extern "C" void __real_##NAME(b3BodyId,b3Vec3,b3Pos,bool) __attribute__((weak));extern "C" void __wrap_##NAME(b3BodyId id,b3Vec3 impulse,b3Pos point,bool wake){assert(__real_##NAME);char input[256];std::snprintf(input,sizeof(input),"{\"impulse\":[%.9g,%.9g,%.9g],\"point\":[%.9g,%.9g,%.9g],\"wake\":%s}",impulse.x,impulse.y,impulse.z,(double)point.x,(double)point.y,(double)point.z,wake?"true":"false");property_event(#NAME,"before",{id,CPU},input);__real_##NAME(id,impulse,point,wake);property_event(#NAME,"after",{id,CPU},input);}
#define PROPERTY_CENTER(NAME,CPU) extern "C" void __real_##NAME(b3BodyId,b3Vec3,bool) __attribute__((weak));extern "C" void __wrap_##NAME(b3BodyId id,b3Vec3 impulse,bool wake){assert(__real_##NAME);char input[192];std::snprintf(input,sizeof(input),"{\"impulse\":[%.9g,%.9g,%.9g],\"wake\":%s}",impulse.x,impulse.y,impulse.z,wake?"true":"false");property_event(#NAME,"before",{id,CPU},input);__real_##NAME(id,impulse,wake);property_event(#NAME,"after",{id,CPU},input);}
#define PROPERTY_TARGET(NAME,CPU) extern "C" void __real_##NAME(b3BodyId,b3WorldTransform,float,bool) __attribute__((weak));extern "C" void __wrap_##NAME(b3BodyId id,b3WorldTransform target,float dt,bool wake){assert(__real_##NAME);char input[256];std::snprintf(input,sizeof(input),"{\"target\":{\"p\":[%.9g,%.9g,%.9g],\"q\":[%.9g,%.9g,%.9g,%.9g]},\"dt\":%.9g,\"wake\":%s}",(double)target.p.x,(double)target.p.y,(double)target.p.z,target.q.v.x,target.q.v.y,target.q.v.z,target.q.s,dt,wake?"true":"false");property_event(#NAME,"before",{id,CPU},input);__real_##NAME(id,target,dt,wake);property_event(#NAME,"after",{id,CPU},input);}
